<script setup lang="ts">
import { computed } from 'vue'
import type { SearchState } from '../types/search'
import { assessmentProtocol, decisionScore, protocolLabel } from '../utils/decisionOverview'
import AssessmentPlot from './AssessmentPlot.vue'

const props = defineProps<{ state: SearchState }>()
const emit = defineEmits<{ navigate: [view: string, candidateId?: string, axis?: string] }>()
const candidates = computed(() => props.state.candidates ?? [])
const selected = computed(() => candidates.value.find(c => c.id === props.state.selected_candidate_id))
const scored = computed(() => candidates.value.filter(c => decisionScore(props.state, c) !== null))
const actions = computed(() => (props.state.actions ?? []).filter(a => a.action !== 'model_decision' || !['completed', 'succeeded'].includes(a.status)))
const selectedAction = computed(() => [...actions.value].reverse().find(a => a.candidate_id === selected.value?.id))
const recipe = computed(() => props.state.registry?.find(r => r.id === selected.value?.id))
const recent = computed(() => actions.value.slice(-4))
const panel = computed(() => typeof props.state.panel === 'object' ? props.state.panel : null)
const pct = (value: number | null) => value === null ? '未取得完整主分数' : `${(value * 100).toFixed(2)}%`
const series = computed(() => [{ name: '主评分', connect: false, points: candidates.value.map((c, i) => ({ x: i + 1, y: decisionScore(props.state, c), label: `${c.title || c.id} · ${protocolLabel(props.state, c)}` })) }])
const statusLabel = (s: string) => ({ interrupted: '已中断', evaluated: '已评价', completed: '已完成', running: '执行中', pending: '等待执行', failed: '失败', execution_failure: '执行失败', resource_failure: '资源不足', evaluating: '评价中', proposed: '已提议', rejected: '已拒绝', skipped: '已跳过', succeeded: '已完成', cancelled: '已取消', unavailable: '无法核验', matched: '符合预测', contradicted: '与预测不符' }[s] || s)
const actionLabel = (s: string) => ({ initial_schedule: '安排起点方案', propose_candidate: '提出新方案', request_evidence: '补充依据', finish: '结束搜索', model_decision: '选择下一步', invalid_proposal: '拒绝无效提案' }[s] || s)
const steps = [
  { title: '观察信号', text: '各处理阶段的功率谱、幅度与通道相关性。', view: 'assessment', axis: 'quality', link: '查看信号图表' },
  { title: '理解方案', text: '处理顺序、参数，以及各步骤的执行情况。', view: 'assessment', axis: 'parameters', link: '查看处理与参数' },
  { title: '比较效果', text: '模型表现、被试差异与评价覆盖。', view: 'assessment', axis: 'utility', link: '查看指标与覆盖' },
  { title: '追溯决策', text: '提案理由、竞争解释与预测核验。', view: 'rounds', axis: undefined, link: '查看完整决策记录' },
]
</script>

<template>
  <section class="decision-overview" aria-label="决策概览">
    <header class="overview-heading"><div><h2>预处理结果</h2></div><span class="scope">开发评估</span></header>
    <div class="decision-result">
      <div><span class="kicker">{{ state.selected_candidate_id ? '所选方案' : '选择状态' }}</span><h3>{{ selected?.title || state.selected_candidate_id || '尚未选定方案' }}</h3><p v-if="!state.selected_candidate_id">候选评估中，尚无最终选择。</p><p v-if="!['completed','stopped'].includes(state.status)" class="limit">搜索尚未完成，以下为已有结果。</p></div>
      <div class="primary-score"><strong>{{ selected ? pct(decisionScore(state, selected)) : '—' }}</strong><span>{{ protocolLabel(state, selected) }}</span><small>{{ scored.length }} / {{ candidates.length }} 个候选有主分数</small></div>
    </div>
    <div class="evidence-route"><article v-for="(step, i) in steps" :key="step.title"><span class="step-number">0{{ i+1 }}</span><h3>{{ step.title }}</h3><p>{{ step.text }}</p><button @click="emit('navigate', step.view, selected?.id, step.axis)">{{ step.link }} →</button></article></div>
    <section class="overview-section"><h3>评分规则与范围</h3><p v-if="assessmentProtocol(state, selected) === 'eegnet'">主评分：EEGNet 三个种子（17、42、2026）的被试宏平均 BA 等权均值。三个种子全部完成后评分，CSP-LDA 为对照。</p><p v-else-if="assessmentProtocol(state, selected) === 'legacy-suite'">历史评分：CSP-LDA、FBCSP、TS-LR 的被试宏平均 BA 等权均值。</p><p v-else>评价器与主分数见上方；更多配置可在运行参数中查看。</p><p v-if="['highest_complete_eegnet_three_seed_utility','highest_complete_three_learner_utility'].includes(String(state.protocol?.selection))">选择完整主分数最高的候选。<template v-if="Array.isArray(state.protocol?.tie_break)">分数相同时依次优先：{{ state.protocol.tie_break.map((key: string) => ({reference:'参考方案优先',fewer_operators:'算子较少优先',candidate_id:'候选编号排序'}[key] || key)).join(' → ') }}。</template></p><p>开发结果用于选择候选，泛化表现仍需独立测试。信号质量指标用于辅助诊断。</p><p v-if="panel">本次范围：{{ panel.development_subjects?.length ?? '未记录' }} 名开发被试 · {{ panel.eligible_count ?? '未记录' }} 个合格试次 · {{ panel.folds?.length ?? '未记录' }} 个外折。</p><p v-if="typeof state.panel === 'string'">评价范围：{{ state.panel }}</p><p v-if="!panel && !state.panel">评价范围未记录。</p><p v-if="selected?.receipt?.representation?.transductive">本方案使用目标被试整批无标签数据进行适配，属于离线转导条件；部署时需要同等信息条件。</p></section>
    <section v-if="selected" class="overview-section"><h3>所选方案的处理顺序</h3><ol v-if="recipe" class="recipe"><li v-for="node in recipe.recipe.nodes" :key="node.id"><strong>{{ state.protocol?.space?.operators.find(o => o.id === node.operator)?.title || node.operator }}</strong><span v-for="(value, key) in node.parameters" :key="key">{{ key }} = {{ value }}</span></li></ol><p v-else>处理顺序未记录。</p><p v-if="recipe" class="muted">逐记录执行情况见“实际执行与参数”。</p><p v-if="selectedAction?.reason"><strong>提案理由：</strong>{{ selectedAction.reason }}</p><p v-else class="muted">提案理由未记录。</p><button @click="emit('navigate', 'assessment', selected.id, 'parameters')">核对实际执行与参数 →</button></section>
    <section class="overview-section"><h3>候选比较</h3><AssessmentPlot v-if="scored.length" title="候选主评分" :series="series" x-label="候选序号（按记录顺序）" y-label="开发 BA（0–1）" :y-domain="[0,1]" :reference=".5" caption="每点为一个候选的开发主分数，按记录顺序排列。无分数的候选不绘点；虚线为 BA=0.5 参考线。" :provenance="{ search_id: state.id, protocol: state.protocol?.assessment || state.protocol?.evaluator, selected_candidate_id: state.selected_candidate_id }" /><ul class="candidate-list"><li v-for="candidate in candidates" :key="candidate.id"><div><strong>{{ candidate.title || candidate.id }}</strong><small>{{ statusLabel(candidate.status) }}<template v-if="candidate.id === state.selected_candidate_id"> · 已选中</template></small><details v-if="candidate.error" class="limit"><summary>失败或中断原因</summary><p>{{ candidate.error }}</p></details></div><span>{{ pct(decisionScore(state, candidate)) }}</span><button @click="emit('navigate', 'assessment', candidate.id, 'utility')">查看证据 →</button></li></ul><p v-if="!candidates.length">暂无候选结果。</p></section>
    <section class="overview-section"><div class="section-heading"><h3>最近的决策与核验</h3><button @click="emit('navigate', 'rounds')">全部 {{ actions.length }} 条记录 →</button></div><p v-if="!recent.length">暂无决策记录。</p><article v-for="action in recent" :key="action.index" class="decision-card"><small>记录 {{ action.index }} · {{ statusLabel(action.status) }}</small><h4>{{ actionLabel(action.action) }}</h4><p>{{ action.reason || '未附说明。' }}</p><template v-if="action.request?.hypothesis"><p><strong>待检验的解释：</strong>{{ action.request.hypothesis.explanation }}</p><p><strong>竞争解释：</strong>{{ action.request.hypothesis.competing_explanation }}</p></template><ul v-if="action.result?.prediction_checks"><li v-for="(check,i) in action.result.prediction_checks.checks" :key="i">{{ check.explanation || check.metric }} — {{ statusLabel(check.status) }}<small>{{ check.metric }} · {{ check.before ?? '未取得' }} → {{ check.after ?? '未取得' }}</small></li></ul><p v-else class="muted">暂无预测核验结果。</p><details v-if="action.error" class="limit"><summary>查看失败或拒绝原因</summary><p>{{ action.error }}</p></details><button v-if="action.candidate_id" @click="emit('navigate', 'assessment', action.candidate_id, 'utility')">查看关联候选 →</button></article><p class="muted">“符合预测”表示记录中的测量方向符合预期，不能单独证明机制或因果关系。</p></section>
    <footer><span>报告、模型与原始记录</span><button @click="emit('navigate', 'artifacts')">打开报告与文件 →</button></footer>
  </section>
</template>

<style scoped>
.decision-overview{color:#28433e;font-size:14px;line-height:1.8}.overview-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.overview-heading h2{font-size:26px;margin:4px 0;font-weight:600}.overview-heading p{margin:0;color:#5c7470}.eyebrow,.kicker{font-size:12px;color:#34796e;letter-spacing:.06em}.scope{font-size:12px;white-space:nowrap;border:1px solid #d1dfd9;border-radius:20px;padding:4px 12px}.decision-result{display:grid;grid-template-columns:1.4fr 1fr;gap:28px;background:#eff6f3;border:1px solid #d6e6df;border-radius:14px;padding:24px;margin:24px 0}.decision-result h3{font-size:21px;margin:5px 0}.decision-result p{margin:4px 0;color:#516e63}.primary-score{border-left:1px solid #d1e1d8;padding-left:24px;display:flex;flex-direction:column;justify-content:center}.primary-score strong{font-size:30px;font-weight:600;color:#246b57}.primary-score span,.primary-score small{font-size:12px;color:#526e64}.evidence-route{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.evidence-route article{display:flex;flex-direction:column;border:1px solid #e0e7e5;border-radius:10px;padding:18px;background:#fff}.step-number{font-size:12px;color:#689288}.evidence-route h3{margin:4px 0}.evidence-route p{font-size:13px;color:#5e756c;margin:6px 0 18px;flex:1}button{font:inherit;font-size:12px;cursor:pointer;border:1px solid #cbdcd3;border-radius:6px;background:#fff;color:#236951;padding:7px 11px;text-align:left}button:hover{background:#edf5f0}button:focus-visible{outline:2px solid #367963;outline-offset:3px}.overview-section{padding-top:26px;margin-top:26px;border-top:1px solid #e0e7e4}.overview-section h3{font-size:17px;margin:0 0 12px}.overview-section p{margin:8px 0}.recipe{display:flex;flex-wrap:wrap;gap:12px;padding-left:22px}.recipe li{padding:10px 16px;background:#f4f7f6;border-radius:8px}.recipe span,.candidate-list small,.decision-card small{display:block;font-size:12px;color:#5e756c}.candidate-list{list-style:none;padding:0}.candidate-list li{display:flex;align-items:center;gap:20px;justify-content:space-between;padding:16px 0;border-bottom:1px solid #edf1ee}.candidate-list li>div{flex:1}.candidate-list li>span{font-variant-numeric:tabular-nums}.muted{color:#637b70;font-size:13px}.limit{color:#8b6032!important;overflow-wrap:anywhere;max-height:160px;overflow:auto}.section-heading,footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.decision-card{padding:18px 20px;border-left:3px solid #8cb5a7;background:#f7f9f8;margin:14px 0;overflow-wrap:anywhere}.decision-card h4{margin:4px 0;font-size:15px}footer{padding:20px;background:#f0f5f2;border-radius:10px;margin-top:28px;font-size:13px}@media(max-width:1100px){.evidence-route{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.decision-result{grid-template-columns:1fr;padding:18px;gap:16px}.primary-score{border-left:0;border-top:1px solid #d1e1d8;padding:14px 0 0}.evidence-route{grid-template-columns:1fr}.candidate-list li,footer{flex-wrap:wrap}.candidate-list li>div{flex-basis:100%}.overview-heading h2{font-size:22px}}
</style>
